def solve(s, k):
    n = len(s)
    count = [0] * 26
    for c in s:
        count[ord(c) - ord('a')] += 1
    odd = 0
    for i in range(26):
        if count[i] % 2 == 1:
            odd += 1
    if odd > 1:
        return "NO"
    if k >= odd:
        return "YES"
    for i in range(26):
        if count[i] % 2 == 1:
            k -= 1
            count[i] -= 1
            if k >= 0:
                continue
            else:
                return "NO"
    return "YES"

