def matrixScore(nums):
    n, m = len(nums), len(nums[0])
    for i in range(n):
        if nums[i][0] == 0:
            for j in range(m):
                nums[i][j] = 1 - nums[i][j]
    for j in range(m - 1, -1, -1):
        count = sum([1 for row in nums if row[j] == 1])
        n = len(nums)
        if count < n // 2:
            for i in range(n):
                nums[i][j] = 1 - nums[i][j]
    score = 0
    for i in range(n):
        for j in range(m):
            score += nums[i][j] * (2 ** (m - j - 1))
    return score

def maxStrength(nums):
    if not nums:
        return 0

    max_strength = 1
    is_negative = False
    for num in nums:
        if num < 0:
            is_negative = not is_negative
        else:
            max_strength *= num

    if is_negative:
        return 0
    else:
        return max_strength

def minExtraChar(s, dictionary):
    n = len(s)
    dp = [0] * (n + 1)
    for i in range(n - 1, -1, -1):
        dp[i] = dp[i + 1] + 1
        for word in dictionary:
            if i + len(word) <= n and s[i: i + len(word)] == word:
                dp[i] = min(dp[i], dp[i + len(word)])
    return dp[0]

def buy_chocolates(prices, money):
    prices.sort()
    for i in range(len(prices) - 1):
        if prices[i] + prices[i + 1] <= money:
            return money - (prices[i] + prices[i + 1])
    return money

def count_adjacent_elements(n, queries):
    # Initialize the array with zeros
    nums = [0] * n

    # Initialize the result array
    result = []

    # Iterate over the queries
    for index_i, color_i in queries:
        # Set the color of the current element
        nums[index_i] = color_i

        # Count the number of adjacent elements with the same color
        count = 0
        for i in range(index_i - 1, -1, -1):
            if nums[i] == nums[index_i]:
                count += 1
            else:
                break

        # Count the number of adjacent elements with the same color
        count += 1
        for i in range(index_i + 1, n):
            if nums[i] == nums[index_i]:
                count += 1
            else:
                break

        # Append the count to the result array
        result.append(count)

    return result

def sum_of_power(nums):
    MOD = 10**9 + 7
    n = len(nums)
    nums.sort()
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    dp[0][0] = 1
    for i in range(1, n + 1):
        for j in range(i + 1):
            dp[i][j] = (dp[i - 1][j] + dp[i - 1][j - 1]) % MOD
            if j > 0:
                dp[i][j] = (dp[i][j] + nums[i - 1] * dp[i - 1][j - 1]) % MOD
    return sum(dp[n]) % MOD

def min_operations(nums):
    n = len(nums)
