def minimize_string(s):
    i = 0
    while i < len(s):
        c = s[i]
        left = s[:i].count(c)
        right = s[i+1:].count(c)
        if left > 0 and right > 0:
            s = s[:i] + s[i+left+right:]
            i = 0
        else:
            i += 1
    return len(s)

def can_traverse_all_pairs(nums):
    def gcd(a, b):
        if b == 0:
            return a
        return gcd(b, a % b)

    n = len(nums)
    visited = [False] * n
    stack = [0]
    while stack:
        node = stack.pop()
        visited[node] = True
        for i in range(n):
            if not visited[i] and gcd(nums[node], nums[i]) > 1:
                stack.append(i)
    return all(visited)

def smallest_string(s):
    n = len(s)
    for i in range(n):
        if s[i] != 'a':
            s = s[:i] + chr(ord('a') - (ord(s[i]) - ord('a'))) + s[i+1:]
            break
    return s

def count_beautiful_pairs(nums):
    def gcd(a, b):
        if b == 0:
            return a
        return gcd(b, a % b)

    def is_coprime(a, b):
        return gcd(a, b) == 1

    count = 0
    for i in range(len(nums)):
        for j in range(i + 1, len(nums)):
            if is_coprime(nums[i][0], nums[j][-1]):
                count += 1
    return count

def min_operations(num1: int, num2: int) -> int:
