    num1 -= num2
    count = 0
    while num1 > 0:
        if num1 >= 2:
            num1 -= 2
            count += 1
        elif num1 >= 4:
            num1 -= 4
            count += 1
        elif num1 >= 8:
            num1 -= 8
            count += 1
        elif num1 >= 16:
            num1 -= 16
            count += 1
        elif num1 >= 32:
            num1 -= 32
            count += 1
        elif num1 >= 64:
            num1 -= 64
            count += 1
        else:
            return -1
