def maxNumberOfFamilies(words):
    word_dict = {}
    for word in words:
        if word not in word_dict:
            word_dict[word] = 1
        else:
            word_dict[word] += 1

    max_pairs = 0
    for word, count in word_dict.items():
        if count == 1:
            max_pairs += 1
        elif count == 2:
            max_pairs += 1
        elif count == 3:
            max_pairs += 1
        else:
            max_pairs += 2

