        return (y + 1) * 2 + (z + 1) * 2

def min_length(words):
    n = len(words)
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        dp[i][i] = len(words[i - 1])
        for j in range(i + 1, n + 1):
            dp[i][j] = min(dp[i][j - 1] + len(words[j - 1]), dp[i - 1][j] + len(words[i - 1]))
    return dp[n][n]

def max_jumps(nums, target):
    n = len(nums)
    dp = [0] * n
    dp[0] = 0
    for i in range(1, n):
        for j in range(i):
            if abs(nums[i] - nums[j]) <= target and dp[j] + 1 > dp[i]:
                dp[i] = dp[j] + 1
        if dp[i] == 0:
            return -1
    return dp[-1]

def count_complete_subarrays(nums):
    n = len(nums)
    count = 0
    for i in range(n):
        for j in range(i, n):
            distinct_nums = set(nums[i:j+1])
            if len(distinct_nums) == len(set(nums)):
                count += 1
    return count

def max_distance(mainTank, additionalTank):
