def longest_subarray(nums, threshold):
    l = 0
    max_length = 0
    for r in range(len(nums)):
        if nums[r] % 2 == 0 and all(nums[i] % 2 != nums[i + 1] % 2 for i in range(r)):
            while nums[l] % 2 != 0 or (r - l + 1) > threshold:
                l += 1
            max_length = max(max_length, r - l + 1)
    return max_length

def numberOfGoodSubarraySplits(nums):
    MOD = 10**9 + 7
    n = len(nums)
    count = 0
    for i in range(n):
        if nums[i] == 1:
            count += 1
        else:
            break
    if count == 0:
        return 0
    else:
        count = 1
        for i in range(n):
            if nums[i] == 1:
                count += 1
            else:
                break
        return count

def count_continuous_subarrays(nums):
    n = len(nums)
    prefix = [0] * n
    prefix[0] = nums[0]
    for i in range(1, n):
        prefix[i] = prefix[i - 1] + nums[i]
    count = 0
    for i in range(n):
        for j in range(i + 1, n):
            if abs(nums[i] - nums[j]) <= 2:
                count += 1
    return count

def maxAlternatingSubarrayLength(nums):
    n = len(nums)
    if n < 2:
        return -1
    dp = [0] * n
    dp[0] = 1
    for i in range(1, n):
        if nums[i] == nums[i-1] + 1:
            dp[i] = dp[i-1] + 1
        else:
            dp[i] = 1
    return max(dp)

def prime_number_pairs(n):
    primes = [i for i in range(2, n+1) if all(i % p != 0 for p in range(2, int(i**0.5)+1))]
    pairs = []
    for i in range(len(primes)):
        for j in range(i+1, len(primes)):
            if primes[i] + primes[j] == n:
                pairs.append([primes[i], primes[j]])
    pairs.sort()
    return pairs

def find_string(a, b, c):
    # Create a list of all possible substrings of a, b, and c
    substrings = [a, b, c]
    substrings.extend([s + t for s in substrings for t in substrings if s != t])
    substrings.extend([s + t + s for s in substrings for t in substrings if s != t])

    # Find the minimum length string that contains all substrings
    min_length = min(len(s) for s in substrings)
    for s in substrings:
        if len(s) == min_length:
            return s

def canMakeAllZero(nums, k):
    total = sum(nums)
    if total % k != 0:
        return False
    target = total // k
    for num in nums:
        if num != target:
            return False
    return True

def min_changes(s, k):
    n = len(s)
    dp = [[0] * (k + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        dp[i][1] = sum(1 for j in range(i) if s[j] != s[i - 1 - j])
    for i in range(2, k + 1):
        for j in range(1, n + 1):
            dp[j][i] = min(dp[j][i - 1] + 1, dp[j - 1][i - 1] + 1)
            for m in range(1, j // 2 + 1):
                if j % m == 0:
                    dp[j][i] = min(dp[j][i], dp[m][i - 1] + dp[j - m][i - 1])
    return dp[n][k]

def split_strings(words, separator):
    result = []
    for word in words:
        for i in range(len(word)):
            if word[i] == separator:
                result.append(word[:i])
                result.append(word[i+1:])
                break
    return result

def solve(n, x):
    MOD = 10**9 + 7
    dp = [0] * (n + 1)
    dp[0] = 1
    for i in range(1, n + 1):
        for j in range(1, i + 1):
            if j**x <= i:
                dp[i] = (dp[i] + dp[i - j**x]) % MOD
    return dp[n]

def min_beautiful_substrings(s):
    def is_beautiful(s):
        if s[0] == '0':
            return False
        return int(s, 2) % 5 == 0

    def dfs(start, count):
        if start == len(s):
            return count
        if is_beautiful(s[start:]):
            return dfs(start + 1, count + 1)
        return min(dfs(start + i, count + 1) for i in range(1, len(s) - start + 1) if is_beautiful(s[start:start + i]))

    return dfs(0, 0)

def longest_valid_substring(word, forbidden):
    n = len(word)
    dp = [0] * (n + 1)
    for i in range(1, n + 1):
        for j in range(i):
            if word[j:i] in forbidden:
                dp[i] = max(dp[i], dp[j])
            else:
                dp[i] = max(dp[i], dp[j] + 1)
    return max(dp)

def faulty_keyboard(s):
    result = ""
    for char in s:
        if char == 'i':
            result = result[::-1]
        else:
            result += char
    return result

def sort_vowels(s):
    vowels = 'aeiouAEIOU'
    vowels_indices = [i for i, char in enumerate(s) if char in vowels]
    vowels_sorted = sorted([s[i] for i in vowels_indices])
    result = list(s)
    for i, char in enumerate(s):
        if char in vowels:
            result[vowels_indices[i]] = vowels_sorted.pop(0)
    return ''.join(result)

def min_split(nums):
    freq = {}
    for num in nums:
        freq[num] = freq.get(num, 0) + 1

    dominant = max(freq, key=freq.get)
    count = freq[dominant]

    for i in range(len(nums) - 1, 0, -1):
        if count * 2 > i + 1:
            return i

    return -1

def maxBeauty(nums, k):
    n = len(nums)
    nums.sort()
    max_beauty = 1
    for i in range(1, n):
        if nums[i] - nums[i-1] <= k:
            max_beauty = max(max_beauty, i)
    return max_beauty

def maxScore(nums, x):
    n = len(nums)
    dp = [0] * n
    dp[0] = nums[0]
    for i in range(1, n):
        if nums[i] % 2 == 0:
            dp[i] = max(dp[i-1] + nums[i], dp[i-1] - x)
        else:
            dp[i] = max(dp[i-1] + nums[i], dp[i-1])
    return max(dp)

def maxSum(nums):
    max_digit = -1
    max_sum = -1
    for i in range(len(nums)):
        for j in range(i+1, len(nums)):
            if max_digit == max_digit(nums[i]) == max_digit(nums[j]):
                max_sum = max(max_sum, nums[i] + nums[j])
    return max_sum

def max_digit(n):
    max_digit = 0
    while n > 0:
        max_digit = max(max_digit, n % 10)
        n //= 10
    return max_digit

def count_interesting_subarrays(nums, modulo, k):
    n = len(nums)
    count = 0
    prefix = [0] * (n + 1)
    for i in range(n):
        prefix[i + 1] = (prefix[i] + nums[i]) % modulo
    for i in range(n):
        for j in range(i, n):
            if (prefix[j + 1] - prefix[i]) % modulo == k:
                count += 1
    return count

def can_split(nums, m):
    def dfs(i, total, count, used):
        if i == len(nums):
            return count == n
        if total >= m:
            return dfs(i + 1, total - nums[i], count + 1, used)
        for j in range(i + 1, len(nums) + 1):
            if not used[j - 1]:
                used[j - 1] = True
                if dfs(j, total + nums[i], count, used):
                    return True
                used[j - 1] = False
        return False

    n = len(nums)
    return dfs(0, 0, 0, [False] * (n + 1))

def count_pairs(nums, target):
    count = 0
    for i in range(len(nums)):
        for j in range(i+1, len(nums)):
            if nums[i] + nums[j] < target:
                count += 1
    return count

def max_groups(usageLimits):
    n = len(usageLimits)
    groups = [0] * n
    groups[0] = 1
    for i in range(1, n):
        groups[i] = min(groups[i-1], usageLimits[i-1])
    return sum(groups)

def stepping_numbers(low, high):
    MOD = 10**9 + 7
    low = int(low)
    high = int(high)
    low_digits = len(str(low))
    high_digits = len(str(high))
    if low_digits > high_digits:
        return 0
    if low_digits == 1:
        return high - low + 1
    if low_digits == 2:
        return (high - low + 1) * 2
    if low_digits == 3:
        return (high - low + 1) * 3
    if low_digits == 4:
        return (high - low + 1) * 4
    if low_digits == 5:
        return (high - low + 1) * 5
    if low_digits == 6:
        return (high - low + 1) * 6
    if low_digits == 7:
        return (high - low + 1) * 7
    if low_digits == 8:
        return (high - low + 1) * 8
    if low_digits == 9:
        return (high - low + 1) * 9
