    mountain_triplets = [[0, 0, 0] for _ in range(n)]

    # Find the mountain triplet for each index
    for i in range(1, n-1):
        for j in range(i+1, n):
            if nums[i] < nums[j] and nums[j] < nums[i+1]:
                mountain_triplets[i][0] = nums[i]
                mountain_triplets[i][1] = nums[j]
                mountain_triplets[i][2] = nums[j+1]
                break

    # Find the minimum possible sum of a mountain triplet
    min_sum = float('inf')
    for triplet in mountain_triplets:
        if triplet[0] != 0 and triplet[1] != 0 and triplet[2] != 0:
