        for j in range(i, n):
            if i == j:
                dp[i][j] = True
            elif s[i] == s[j]:
                dp[i][j] = dp[i + 1][j - 1]
            else:
                dp[i][j] = dp[i + 1][j] or dp[i][j - 1]
    res = []
    for a, b, c, d in queries:
        if a == b or c == d:
