def count_non_ddos_strings(s):
    MOD = 998244353
    n = len(s)
    dp = [[0] * 26 for _ in range(26)]
    for i in range(n):
        if s[i] == '?':
            continue
        if i == 0:
            dp[ord(s[i]) - ord('A')][ord(s[i]) - ord('A')] += 1
        else:
            dp[ord(s[i]) - ord('A')][ord(s[i-1]) - ord('A')] += 1
    for i in range(1, 26):
        dp[i][i] = 1
    for i in range(2, 26):
        for j in range(1, 26):
            dp[i][j] = (dp[i][j] + dp[i-1][j] + dp[i][j-1] - dp[i-1][j-1]) % MOD
    ans = 0
    for i in range(26):
        for j in range(26):
            if i == j:
                ans = (ans + dp[i][j]) % MOD
    return ans
