def is_good_graph():
    N, M = map(int, input().split())
    edges = [list(map(int, input().split())) for _ in range(M)]
    K = int(input())
    x, y = [list(map(int, input().split())) for _ in range(K)]
    Q = int(input())
    p, q = [list(map(int, input().split())) for _ in range(Q)]

    # Create adjacency list
    adj_list = [[] for _ in range(N)]
    for u, v in edges:
        adj_list[u-1].append(v-1)
        adj_list[v-1].append(u-1)

    # Check if there is a path between x_i and y_i
    def has_path(x, y):
        visited = [False] * N
        def dfs(node):
            if node == y:
                return True
            visited[node] = True
            for neighbor in adj_list[node]:
                if not visited[neighbor]:
                    if dfs(neighbor):
                        return True
            return False
        return dfs(x)

    # Check if the graph is good
    def is_good():
        for i in range(K):
            if has_path(x[i]-1, y[i]-1):
                return False
        return True

    # Check if the graph is good for each question
    for i in range(Q):
        if is_good():
            print("Yes")
        else:
            print("No")

