def snuke_path():
    H, W = map(int, input().split())
    S = [input() for _ in range(H)]

    def is_valid(i, j):
        return 0 <= i < H and 0 <= j < W

    def dfs(i, j, path):
        if not is_valid(i, j):
            return False
        if i == H - 1 and j == W - 1:
            return True
        if path[-1] == S[i][j]:
            return dfs(i + 1, j, path + [(i, j)]) or dfs(i, j + 1, path + [(i, j)])
        return False

    return "Yes" if dfs(0, 0, [(0, 0)]) else "No"

