    # Initialize the grid with zeros
    grid = [[0 for _ in range(W+1)] for _ in range(H+1)]

    # Mark the holed squares
    for i, j in zip(a, b):
        grid[i][j] = 1

    # Count the number of holeless squares
    count = 0
    for i in range(1, H+1):
        for j in range(1, W+1):
            if grid[i][j] == 0:
                # Check if the square region is holeless
                for k in range(1, min(N+1, i+1)):
                    for l in range(1, min(N+1, j+1)):
                        if grid[i-k][j-l] == 1:
                            break
                    else:
                        count += 1
    return count
