def find_strongest_programmer(N, M, A, B):
    # Create a dictionary to store the superiority relations
    superiority = {i: [] for i in range(1, N+1)}
    for i in range(M):
        a, b = A[i], B[i]
        superiority[a].append(b)
        superiority[b].append(a)

    # Create a list to store the strongest programmers
    strongest_programmers = []

    # Iterate over all programmers
    for i in range(1, N+1):
        # If the programmer is not in the strongest programmers list, add it
        if i not in strongest_programmers:
            # Create a set to store the programmers stronger than the current programmer
            stronger_programmers = set()
            # Iterate over all programmers
            for j in range(1, N+1):
                # If the current programmer is stronger than the programmer j, add j to the set
                if j in superiority[i]:
                    stronger_programmers.add(j)
            # If the current programmer is stronger than all programmers, add it to the strongest programmers list
            if len(stronger_programmers) == len(set(range(1, N+1)) - {i}):
                strongest_programmers.append(i)

    # If there is only one strongest programmer, return its number
    if len(strongest_programmers) == 1:
        return strongest_programmers[0]
    # If there are multiple strongest programmers, return -1
    else:
        return -1
