def kth_321_like_number(k):
    def is_321_like_number(n):
        digits = [int(d) for d in str(n)]
        return all(digits[i] > digits[i+1] for i in range(len(digits)-1))

    def next_321_like_number(n):
        digits = [int(d) for d in str(n)]
        i = len(digits) - 2
        while i >= 0 and digits[i] >= digits[i+1]:
            i -= 1
        if i < 0:
            return None
        j = len(digits) - 1
        while digits[j] <= digits[i]:
            j -= 1
        digits[i], digits[j] = digits[j], digits[i]
        digits[i+1:] = digits[i+1:][::-1]
        return int(''.join(map(str, digits)))

    current_number = 0
    while True:
        if is_321_like_number(current_number):
            k -= 1
            if k == 0:
                return current_number
        current_number = next_321_like_number(current_number + 1)

