import sys
import heapq

def solve():
    N, M, K = map(int, input().split())
    edges = [list(map(int, input().split())) for _ in range(M)]
    edges.sort(key=lambda x: x[2])

    def dijkstra(start):
        dist = [float('inf')] * N
        dist[start] = 0
        pq = [(0, start)]
        while pq:
            d, u = heapq.heappop(pq)
            if d > dist[u]:
                continue
            for v, w in edges:
                if dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w
                    heapq.heappush(pq, (dist[v], v))
        return dist

    min_cost = float('inf')
    for i in range(M):
        dist = dijkstra(i)
        for j in range(i+1, M):
            dist2 = dijkstra(j)
            for k in range(N):
                if dist[k] == float('inf') or dist2[k] == float('inf'):
                    continue
                min_cost = min(min_cost, (dist[k] + dist2[k]) % K)
    print(min_cost)

