def make_grid_identical(A, B):
    H, W = len(A), len(A[0])
    if H != len(B) or W != len(B[0]):
        return -1

    A = [list(map(int, line.split())) for line in A]
    B = [list(map(int, line.split())) for line in B]

    def swap_rows(A, i, j):
        A[i], A[j] = A[j], A[i]

    def swap_columns(A, i, j):
        A[:, i], A[:, j] = A[:, j], A[:, i]

    def count_operations(A, B):
        count = 0
        for i in range(H):
            for j in range(W):
                if A[i][j] != B[i][j]:
                    count += 1
                    if i > 0:
                        swap_rows(A, i, i-1)
                    if j > 0:
                        swap_columns(A, j, j-1)
        return count

    return count_operations(A, B)

