def game_winner():
    # Read the input grid
    grid = [list(map(int, input().split())) for _ in range(3)]

    # Function to check if there are three consecutive cells of the same color in a row, column, or diagonal
    def check_sequence(grid, color):
        for i in range(3):
            if all(grid[i][j] == color for j in range(3)):
                return True
            if all(grid[j][i] == color for j in range(3)):
                return True
        if all(grid[i][i] == color for i in range(3)):
            return True
        if all(grid[i][2-i] == color for i in range(3)):
            return True
        return False

    # Function to calculate the total score
    def calculate_score(grid):
        return sum(sum(row) for row in grid)

    # Function to determine the winner
    def determine_winner(grid):
        # Check if there are three consecutive cells of the same color in any row, column, or diagonal
        if check_sequence(grid, 'R') or check_sequence(grid, 'B'):
            return 'Takahashi'
        # Check if there are white cells left
        if any(cell == 0 for row in grid for cell in row):
            return 'Aoki'
        # If no three consecutive cells of the same color are found and there are no white cells left, the game ends
        return 'Takahashi' if calculate_score(grid) > 0 else 'Aoki'

    # Determine the winner
    winner = determine_winner(grid)
    print(winner)

