def attraction_guide(N, K, A):
    start = 0
    while True:
        if len(A) == 0:
            start += 1
            continue
        if A[0][0] > K:
            start += 1
            A[0][0] -= K
        else:
            A[0][0] = 0
            A.pop(0)
        if len(A) == 0:
            break
    return start

