def min_deletions(word, k):
    freq = [0]*26
    for c in word:
        freq[ord(c) - ord('a')] += 1
    min_deletions = float('inf')
    for i in range(26):
        if freq[i] > 0:
            freq[i] -= 1
            min_deletions = min(min_deletions, sum(abs(freq[i] - freq[j]) for j in range(26)) - k)
