def longest_subarray(nums):
    n = len(nums)
    max_len = 1
    increasing = [1] * n
    decreasing = [1] * n
    for i in range(1, n):
        if nums[i] > nums[i-1]:
            increasing[i] = increasing[i-1] + 1
        if nums[i] < nums[i-1]:
            decreasing[i] = decreasing[i-1] + 1
    for i in range(n-2, -1, -1):
        if nums[i] > nums[i+1]:
            increasing[i] = max(increasing[i], increasing[i+1] + 1)
        if nums[i] < nums[i+1]:
            decreasing[i] = max(decreasing[i], decreasing[i+1] + 1)
    for i in range(n):
        max_len = max(max_len, increasing[i], decreasing[i])
    return max_len

def smallest_string(s, k):
    n = len(s)
    min_dist = [0] * n
    min_dist[0] = ord(s[0]) - ord('a')
    for i in range(1, n):
        min_dist[i] = min(min_dist[i - 1], ord(s[i]) - ord('a'))
    res = list(s)
    for i in range(n - 1, -1, -1):
        if min_dist[i] <= k:
            res[i] = chr(ord('a') + min_dist[i])
            k -= min_dist[i]
        else:
            res[i] = chr(ord('a') + k)
            k = 0
    return ''.join(res)

