def kth_smallest_amount(coins, k):
    def dfs(index, total, k):
        if k == 0:
            return total
        if index == len(coins):
            return float('inf')
        return min(dfs(index + 1, total, k), dfs(index, total + coins[index], k - 1))

    return dfs(0, 0, k)

