    for i in range(len(nums1)):
        for j in range(len(nums2)):
            if nums1[i] % nums2[j] == 0 and nums1[i] // nums2[j] % k == 0:
                count += 1
    return count

def compress(word):
    comp = ""
    for i in range(len(word)):
        count = 1
        while i + 1 < len(word) and word[i] == word[i + 1]:
            i += 1
            count += 1
        comp += str(count) + word[i]
    return comp

def maxSumSubsequence(nums, queries):
    MOD = 10**9 + 7
    n = len(nums)
    dp = [0] * (n + 1)
    dp[0] = nums[0]
    for i in range(1, n):
        dp[i] = max(dp[i - 1], nums[i])
    max_sum = dp[-1]
    for pos, x in queries:
        if pos == 0:
            max_sum = max(max_sum, dp[-1] - nums[pos])
        else:
            max_sum = max(max_sum, dp[pos - 1] + x - nums[pos])
    return max_sum % MOD

def min_partitions(s):
    # Count the frequency of each character
    freq = {}
    for char in s:
        if char in freq:
            freq[char] += 1
        else:
            freq[char] = 1

    # Find the maximum frequency
    max_freq = max(freq.values())

    # If all characters have the same frequency, return 1
    if max_freq == len(s):
        return 1

    # If not, return the number of partitions
    return max_freq

def find_xor(nums):
    xor = 0
    for num in nums:
        xor ^= num
    return xor

def find_occurrences(nums, queries, x):
    result = []
    for q in queries:
        count = 0
        for i in range(len(nums)):
            if nums[i] == x:
                count += 1
                if count == q:
                    result.append(i)
                    break
        else:
            result.append(-1)
    return result
